```bash
# Créer une configuration de distribution CloudFront
cat > cf-config.json <<EOF
{
  "CallerReference": "$(date +%s)",
  "Commentaire": "Distribution de démonstration de l'infrastructure mondiale",
  "DefaultRootObject": "index.html",
  "Origines": {
    "Quantité": 1,
    "Articles": [
      {
        "Id ": "S3-${BUCKET_NAME}",
        "DomainName": "${BUCKET_NAME}.s3.${REGION}.amazonaws.com",
        "S3OriginConfig": {
          "OriginAccessIdentity": ""
        }
      }
    ]
  },
  "DefaultCacheBehavior": {
    "TargetOriginId": "S3-${BUCKET_NAME}",
    "ViewerProtocolPolicy": "redirection vers https",
    "Méthodes autorisées": {
      "Quantité": 2,
      "Articles": ["GET", "HEAD"],
      "MéthodesCached": {
        "Quantité": 2,
        "Articles": ["OBTENIR", "HEAD"]
      }
    },
    "Valeurs transmises": {
      "QueryString" : faux,
      "Cookies": {"Transférer": "aucun"}
    },
    "MinTTL": 0,
    "TTL par défaut": 86400,
    "MaxTTL": 31536000,
    "Compresser" : vrai
  },
  "Activé" : vrai
}
EOF

# Créer la distribution
aws cloudfront créer-distribution \
    --fichier de configuration-distribution://cf-config.json

# Remarque : les distributions CloudFront prennent 15 à 20 minutes à déployer
```

Autoriser les utilisateurs à gérer uniquement les instances EC2 marquées avec leur équipe :
```bash
cat > ec2-team-policy.json <<'EOF'
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Sid": "ViewAllInstances",
      "Effect": "Allow",
      "Action": [
        "ec2:Describe*",
        "ec2:Get*"
      ],
      "Resource": "*"
    },
    {
      "Sid": "ManageTeamInstances",
      "Effect": "Allow",
      "Action": [
        "ec2:StartInstances",
        "ec2:StopInstances",
        "ec2:RebootInstances",
        "ec2:TerminateInstances"
      ],
      "Resource": "arn:aws:ec2:*:*:instance/*",
      "Condition": {
        "StringEquals": {
          "ec2:ResourceTag/Team": "${aws:PrincipalTag/Team}"
        }
      }
    },
    {
      "Sid": "RequireTeamTagOnCreate",
      "Effect": "Allow",
      "Action": "ec2:RunInstances",
      "Resource": "arn:aws:ec2:*:*:instance/*",
      "Condition": {
        "StringEquals": {
          "aws:RequestTag/Team": "${aws:PrincipalTag/Team}"
        }
      }
    },
    {
      "Sid": "AllowLaunchTemplate",
      "Effect": "Allow",
      "Action": "ec2:RunInstances",
      "Resource": [
        "arn:aws:ec2:*:*:network-interface/*",
        "arn:aws:ec2:*:*:subnet/*",
        "arn:aws:ec2:*:*:volume/*",
        "arn:aws:ec2:*:*:security-group/*",
        "arn:aws:ec2:*::image/*"
      ]
    }
  ]
}
EOF

aws iam create-policy \
    --policy-name EC2TeamBasedAccess \
    --policy-document file://ec2-team-policy.json
```
**Tagez l'utilisateur :**
```bash
aws iam tag-user \
    --user-name alice \
    --tags Key=Team,Value=backend
```
Désormais, Alice ne peut gérer que les instances EC2 étiquetées avec « Team=backend ».

Accordez l'accès uniquement pendant les heures de bureau :
```bash
cat > business-hours-policy.json <<'EOF'
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Sid": "AllowDuringBusinessHours",
      "Effect": "Allow",
      "Action": "rds:*",
      "Resource": "*",
      "Condition": {
        "DateGreaterThan": {
          "aws:CurrentTime": "2025-01-01T09:00:00Z"
        },
        "DateLessThan": {
          "aws:CurrentTime": "2025-12-31T18:00:00Z"
        },
        "StringEquals": {
          "aws:RequestedRegion": "us-east-1"
        }
      }
    }
  ]
}
EOF

aws iam create-policy \
    --policy-name BusinessHoursRDSAccess \
    --policy-document file://business-hours-policy.json
```

